def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    danger_count = 0
    rich_aggressive = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                danger_count += 1
            if opp.get('budget', 0) > 700:
                rich_aggressive += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(bid)

    if not alive:
        return min(budget, 18.0)

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 55.0
    max_prev = max(prev_bids) if prev_bids else 70.0

    total_players = len(alive) + 1
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < total_players
    very_tight = expected_units <= max(1.2, total_players * 0.55)

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    pressure = 0
    if max_prev >= 120:
        pressure += 3
    elif max_prev >= 90:
        pressure += 2
    elif max_prev >= 65:
        pressure += 1
    pressure += min(2, danger_count)
    if rich_aggressive >= 2:
        pressure += 1

    if urgency >= 7:
        bid = max(95.0, avg_prev + 8.0)
        if very_tight:
            bid = max(bid, max_prev + 3.0)
    elif urgency >= 4:
        if scarcity:
            bid = max(72.0, avg_prev + 2.5)
        else:
            bid = 54.0 if pressure >= 2 else 42.0
    else:
        if very_tight:
            bid = 61.0 if pressure <= 2 else 74.0
        elif scarcity:
            bid = 44.0 if pressure >= 3 else 34.0
        else:
            bid = 18.0 if pressure >= 2 else 9.0

    if budget < DAILY_SALARY * 2 and urgency < 4:
        bid = min(bid, 28.0)
    if budget < DAILY_SALARY and urgency < 7:
        bid = min(bid, 22.0)

    if hp <= 1 or no_water >= 3:
        bid = max(bid, min(budget, max_prev + 5.0 if prev_bids else 85.0))

    if day == 1 and urgency == 0 and not very_tight:
        bid = min(bid, 20.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents alive, conserve budget.
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only.
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Pressure estimate: if any opponent bid very high yesterday, expect a contest.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units supply can support (used only for scaling).
    # Ensure indices are int-safe (though we won't index arrays).
    supply_units = int(supply / float(WATER_REQ))  # 15-25 => 1-2

    # Baseline bid: aim to secure 1 unit when supply is tight.
    # Use a moderate fraction of daily salary to avoid overpaying.
    if supply_units <= 1:
        base = DAILY_SALARY * 0.65
    else:
        base = DAILY_SALARY * 0.55

    # Adjust based on our HP.
    hp = float(my_status['hp'])
    if hp <= 1.5:
        hp_mult = 1.25
    elif hp <= 3.0:
        hp_mult = 1.05
    else:
        hp_mult = 0.95

    # If opponents were bidding aggressively yesterday, slightly outbid.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        contest_mult = 1.08
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        contest_mult = 1.03
    else:
        contest_mult = 0.98

    bid = base * hp_mult * contest_mult

    # If an opponent survived yesterday with low bids, we can undercut slightly.
    # Use their previous_trace if available.
    lowest_survivor_bid = None
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('hp_after', None) is not None:
            try:
                hp_after = float(prev.get('hp_after'))
            except Exception:
                hp_after = None
            if hp_after is not None and hp_after > 0:
                b = prev.get('bid', None)
                if b is not None:
                    try:
                        b = float(b)
                        if lowest_survivor_bid is None or b < lowest_survivor_bid:
                            lowest_survivor_bid = b
                    except Exception:
                        pass

    if lowest_survivor_bid is not None and lowest_prev_bid := float(lowest_survivor_bid):
        # Undercut if we are far above their typical spending.
        if bid > lowest_prev_bid * 1.25:
            bid = (bid + lowest_prev_bid) / 2.0

    # Hard caps: cannot exceed budget.
    budget = float(my_status['budget'])
    if budget <= 0:
        return 0.0

    # Keep bid within reasonable bounds relative to salary.
    bid_cap = DAILY_SALARY * 0.95
    bid = float(min(bid, bid_cap, budget))

    # If we are low on budget, scale down.
    if budget < DAILY_SALARY * 0.6:
        bid = float(min(bid, budget * 0.9))

    # Ensure non-negative.
    if bid < 0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    EPISODE_DAYS = 10

    bid = DAILY_SALARY * 0.8

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    if yesterday_bids:
        max_opp_bid_yesterday = max(yesterday_bids)
        if max_opp_bid_yesterday >= bid:
            bid = max_opp_bid_yesterday + 5

    if my_status['hp'] <= 3 or my_status['no_water_days'] > 0:
        bid = max(bid, DAILY_SALARY * 1.15)
        if my_status['hp'] == 1:
            bid = max(bid, DAILY_SALARY * 1.5)

    current_supply = day_context['supply']
    if current_supply <= WATER_REQ + 2:
        bid *= 1.2
    elif current_supply <= WATER_REQ + 5:
        bid *= 1.1
    elif current_supply >= MAX_SUPPLY - 5:
        bid *= 0.9

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 2 and my_status['hp'] < 10:
        bid = max(bid, DAILY_SALARY * 1.2)

    bid = min(bid, my_status['budget'])
    bid = max(bid, DAILY_SALARY * 0.4)

    bid = max(bid, 0.01)

    return bid

